/** Hostnames only: keep ports in the initial URL, never silently widen a grant. */
export class BrowserTargetError extends TypeError {
  code = "invalid_arguments";
  requestDispatched = false;
  recovery = {
    action: "correct_browser_hosts",
    instruction:
      "Use hostnames without ports, schemes, paths or wildcards in target.allowedHosts, for example 127.0.0.1. Keep the port in target.initialURL. Include its hostname or an already authorized parent domain. Preserve any original Run; do not replay work with unknown effects.",
  };
}

export function browserHostAllowed(value, allowedHosts) {
  try {
    const { hostname } = new URL(value);
    return allowedHosts.some(
      (host) => hostname === host || hostname.endsWith(`.${host}`),
    );
  } catch {
    return false;
  }
}

export function validateBrowserHosts(initialURL, allowedHosts) {
  if (allowedHosts === undefined) return;
  if (
    !Array.isArray(allowedHosts) ||
    allowedHosts.length === 0 ||
    allowedHosts.some((host) => {
      if (typeof host !== "string" || !host || host.includes("*")) return true;
      try {
        const url = new URL(`http://${host}`);
        return (
          url.hostname !== host ||
          url.host !== host ||
          url.pathname !== "/" ||
          Boolean(url.username || url.password || url.search || url.hash)
        );
      } catch {
        return true;
      }
    })
  )
    throw new BrowserTargetError(
      "target.allowedHosts must contain hostnames without ports, schemes, paths or wildcards. Keep the port in target.initialURL.",
    );
  if (!browserHostAllowed(initialURL, allowedHosts))
    throw new BrowserTargetError(
      "target.allowedHosts does not allow the hostname in target.initialURL. No new browser execution was dispatched.",
    );
}
